const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1100, height: 760 } });
  await page.goto('file:///home/runner/work/PlayGround/PlayGround/index.html');
  await page.waitForTimeout(300);

  // Move white pawn e2 -> e4 (no rules, anything goes) and also a black knight g8 -> f5
  const board = page.locator('#board .square');
  // squares are in display order; with default orientation display row 6 col 4 = e2
  await board.nth(6 * 8 + 4).click(); // e2 white pawn
  await board.nth(4 * 8 + 4).click(); // e4
  // black knight g8 (display row0 col6) -> g5? let's do knight to e5 area: f6? just pick row 3 col 3
  await board.nth(0 * 8 + 6).click(); // g8 black knight
  await board.nth(5 * 8 + 2).click(); // c3
  await page.waitForTimeout(200);

  // Paint mode: place a white queen on d5
  await page.locator('#palette button').nth(1).click(); // white queen
  await board.nth(3 * 8 + 3).click(); // d5
  await page.locator('#palette button').nth(1).click(); // paint off

  await page.screenshot({ path: '/tmp/opencode/chess3.jpg', type: 'jpeg', quality: 80 });
  const log = await page.locator('#log').innerText();
  console.log(log);
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

